import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";

const Movie = ()=>{
    const [movie, setMovie] = useState({});
    let { id } = useParams();

    useEffect(() => {

        let myMovie = {
                id: 1, 
                title: "Highlander",
                release_date: "1986-03-07",
                runtime: 116, 
                mpaa_rating: "R",
                description: "Some long description",
        }

    }, [id])

    return(

        <div>
            <h2>Movie</h2>
            <hr />
        </div>

    )
}

export default Movie;
